    "id": "joan-tyrry-somerset-1555",
    "name": "Joan Tyrry",
    "status": "Survived; Released",
    "trial_id": null,
    "location_id": "essex-county",
    "year_active": 1555,
    "social_status": "Peasant woman, local healer",
